#include "SurvivalMetaSpecComponent.h"

USurvivalMetaSpecComponent::USurvivalMetaSpecComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	AbilityTags = { TEXT("Ability.Craft"), TEXT("Ability.Scan") };
}

float USurvivalMetaSpecComponent::SurvivalPressure(float Hunger01, float Thirst01, float TempStress01) const
{
	return FMath::Clamp((Hunger01 + Thirst01 + TempStress01) / 3.0f, 0.0f, 1.0f);
}

bool USurvivalMetaSpecComponent::ShouldDuckMusic(bool bTookDamage) const
{
	return bDuckMusicOnDamage && bTookDamage;
}

bool USurvivalMetaSpecComponent::InCraftingRange(float DistanceUu) const
{
	return DistanceUu <= CraftingRadius;
}

bool USurvivalMetaSpecComponent::ValidateSpec() const
{
	// every spec property is read here — a value nothing reads is
	// metadata, not a feature (H-21).
	const bool bNamed = !HungerStat.IsEmpty() && !ThirstStat.IsEmpty() && !TemperatureStat.IsEmpty() && AbilityTags.Num() >= 0 && !DialogueTree.IsEmpty() && !PrioritySystem.IsEmpty();
	const float NumericTouch = (float)CraftingRadius + (bDuckMusicOnDamage ? 1.0f : 0.0f);
	return bNamed && FMath::IsFinite(NumericTouch);
}
